-- 011: notifications — one in-app notification system with two producers:
--   kind='price_drop'  auto-generated by the alert worker when a VERIFIED live price
--                      hits a user's tracked target (AI copy from real data only)
--   kind='admin'       pushed from Admin → Notifications (user_id NULL = broadcast)
-- Read state per user lives in notification_reads (broadcasts are unread for everyone
-- until each user reads them; user-targeted notifications use the same mechanism).
CREATE TABLE IF NOT EXISTS notifications (
  id             INT AUTO_INCREMENT PRIMARY KEY,
  user_id        INT          DEFAULT NULL,        -- NULL = broadcast to every visitor
  kind           VARCHAR(20)  NOT NULL,           -- 'price_drop' | 'admin'
  title          VARCHAR(200) NOT NULL,
  body           VARCHAR(1000) NOT NULL,
  image          VARCHAR(1000) DEFAULT NULL,
  cta_url        VARCHAR(1000) DEFAULT NULL,      -- https link opened on click
  search_query   VARCHAR(300) DEFAULT NULL,       -- price_drop: open this product page
  product_title  VARCHAR(300) DEFAULT NULL,
  price_now      INT          DEFAULT NULL,
  price_prev     INT          DEFAULT NULL,
  target_price   INT          DEFAULT NULL,
  seller         VARCHAR(120) DEFAULT NULL,
  is_active      TINYINT(1)   NOT NULL DEFAULT 1,
  created_by     VARCHAR(190) DEFAULT 'system',
  created_at     TIMESTAMP    DEFAULT CURRENT_TIMESTAMP,
  KEY ix_notif_user (user_id),
  KEY ix_notif_active (is_active)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS notification_reads (
  notification_id INT NOT NULL,
  user_id         INT NOT NULL,
  read_at         TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY ux_read (notification_id, user_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
